import json
from pathlib import Path

def load_prompts(p):
    ev = json.loads(Path(p).read_text())
    return {q[\"id\"]: q[\"prompt\"] for q in ev[\"questions\"]}

sub = load_prompts(\"/workspace/submission/evaluation.json\")
probes = {}
for name in [\"probe_v1\",\"probe_v2\",\"probe_v3\",\"probe_v4\",\"probe_v5\",\"pilot_sep\",\"pilot2\",\"pilot_hard\",\"suite\",\"suite_draft\"]:
    p = Path(\"/workspace\")/name/\"evaluation.json\"
    if p.exists():
        prompts = load_prompts(p)
        probes[name] = prompts
        print(name, \"n\", len(prompts))

# compare submission prompts to any probe
mismatch = []
missing = []
for iid, prompt in sub.items():
    found = False
    for name, prompts in probes.items():
        if iid in prompts:
            found = True
            if prompts[iid] "'!= prompt:
                mismatch.append((iid, name, len(prompts[iid]), len(prompt)))
            break
    if not found:
        missing.append(iid)
print("missing from all probes", missing)
print("mismatches", len(mismatch))
for row in mismatch[:30]:
    print(row)

# token cap compare
spec_sub = json.loads(Path("/workspace/submission/grader_spec.json").read_text())["tokens"]
print("'"\\n--- token mismatches vs probes ---\")
for name in [\"probe_v1\",\"probe_v2\",\"probe_v3\",\"probe_v4\",\"probe_v5\"]:
    p = Path(\"/workspace\")/name/\"grader_spec.json\"
    if not p.exists():
        continue
    spec = json.loads(p.read_text())
    toks = spec.get(\"tokens\", {})
    diffs = []
    for iid, cap in spec_sub.items():
        if iid in toks and toks[iid] "'!= cap:
            diffs.append((iid, toks[iid], cap))
    print(name, "token diffs", len(diffs), diffs[:15])

# system prompt compare
for name in ["probe_v5","probe_v4","probe_v1","submission"]:
    text = Path(f"/workspace/{name}/run.py").read_text()
    idx = text.find("system=")
    print(name, "system snippet", text[idx:idx+180].replace("'"\\n\",\" \"))
